import pytest
from app.domain import *
from app.abilities import *
from app.fakes import *
from app.logic import payment_deltas
from datetime import date


def test_payer_to_receiver_250():
    result = payment_deltas(Payment(payment_id='p1', from_member_id='a', to_member_id='b', amount_cents=250, note='dinner', occurred_on=date(2026, 1, 1)))
    expected = {'a': 250, 'b': -250}
    assert result == expected


def test_reverse_direction_one_cent():
    result = payment_deltas(Payment(payment_id='p2', from_member_id='b', to_member_id='a', amount_cents=1, note='', occurred_on=date(2026, 1, 2)))
    expected = {'b': 1, 'a': -1}
    assert result == expected


def test_zero_cent_payment_preserves_both_ids():
    result = payment_deltas(Payment(payment_id='p3', from_member_id='payer', to_member_id='receiver', amount_cents=0, note='zero', occurred_on=date(2026, 1, 3)))
    expected = {'payer': 0, 'receiver': 0}
    assert result == expected


def test_large_amount_and_unrelated_fields_do_not_affect_deltas():
    result = payment_deltas(Payment(payment_id='payment-99', from_member_id='member-x', to_member_id='member-y', amount_cents=987654321, note='anything', occurred_on=date(2025, 12, 31)))
    expected = {'member-x': 987654321, 'member-y': -987654321}
    assert result == expected

