from app.domain import *
from app.abilities import *
from app.fakes import *
from app.logic import undo_last_action
import pytest
from stateless import run, supply

def test_undo_saves_trip_without_final_payment():
    repo = InMemoryTripRepository((Trip('t1', 'Trip', 'USD', (), (), (
        ExpenseAction(Expense('e1', 'm1', Decimal('10.00'), 'USD', SplitKind.EQUAL, (), 'lunch', date(2026, 1, 2))),
        PaymentAction(Payment('p1', 'm2', 'm1', 500, 'payback', date(2026, 1, 3))),
    ), False),))

    result = run(supply(repo)(undo_last_action)('t1'))

    expected_trip = Trip('t1', 'Trip', 'USD', (), (), (
        ExpenseAction(Expense('e1', 'm1', Decimal('10.00'), 'USD', SplitKind.EQUAL, (), 'lunch', date(2026, 1, 2))),
    ), False)

    assert result == expected_trip
    assert repo.trips == {'t1': expected_trip}

def test_undo_only_action_saves_empty_history():
    repo = InMemoryTripRepository((Trip('t1', 'Trip', 'USD', (), (), (
        PaymentAction(Payment('p1', 'm1', 'm2', 123, 'coffee', date(2026, 1, 2))),
    ), False),))

    result = run(supply(repo)(undo_last_action)('t1'))

    expected_trip = Trip('t1', 'Trip', 'USD', (), (), (), False)

    assert result == expected_trip
    assert repo.trips == {'t1': expected_trip}

def test_undo_open_empty_trip_raises_empty_history():
    repo = InMemoryTripRepository((Trip('t1', 'Trip', 'USD', (), (), (), False),))

    with pytest.raises(EmptyHistoryError) as exc_info:
        run(supply(repo)(undo_last_action)('t1'))

    assert str(exc_info.value) == 't1'
    assert repo.trips == {'t1': Trip('t1', 'Trip', 'USD', (), (), (), False)}

def test_undo_closed_trip_with_action_raises_closed_trip():
    repo = InMemoryTripRepository((Trip('t1', 'Trip', 'USD', (), (), (
        ExpenseAction(Expense('e1', 'm1', Decimal('10.00'), 'USD', SplitKind.EQUAL, (), 'lunch', date(2026, 1, 2))),
    ), True),))

    with pytest.raises(ClosedTripError) as exc_info:
        run(supply(repo)(undo_last_action)('t1'))

    assert str(exc_info.value) == 't1'
    assert repo.trips == {'t1': Trip('t1', 'Trip', 'USD', (), (), (
        ExpenseAction(Expense('e1', 'm1', Decimal('10.00'), 'USD', SplitKind.EQUAL, (), 'lunch', date(2026, 1, 2))),
    ), True)}

def test_undo_closed_empty_trip_prioritizes_closed_error():
    repo = InMemoryTripRepository((Trip('t1', 'Trip', 'USD', (), (), (), True),))

    with pytest.raises(ClosedTripError) as exc_info:
        run(supply(repo)(undo_last_action)('t1'))

    assert str(exc_info.value) == 't1'
    assert repo.trips == {'t1': Trip('t1', 'Trip', 'USD', (), (), (), True)}

def test_undo_missing_trip_propagates_not_found():
    repo = InMemoryTripRepository(())

    with pytest.raises(TripNotFoundError) as exc_info:
        run(supply(repo)(undo_last_action)('t1'))

    assert str(exc_info.value) == 't1'
    assert repo.trips == {}
